// The squash token's keys, shared with `wubble_core::motion` (one copy of the table).
#[path = "../wubble-core/src/motion/squash.rs"]
#[allow(dead_code)]
mod squash;

use std::path::PathBuf;

/// Writes `squash-keys.slint` (the `SquashKeys` global) into `out` from `motion::SQUASH_KEYS`.
fn write_squash_keys(out: &std::path::Path) {
    let col = |f: fn(&(f64, f64, f64)) -> f64| {
        squash::SQUASH_KEYS
            .iter()
            .map(|k| format!("{:?}", f(k)))
            .collect::<Vec<_>>()
            .join(", ")
    };
    let text = format!(
        "// Generated by wubble-ui's build.rs from `wubble_core::motion::SQUASH_KEYS`.
export global SquashKeys {{
    out property <[float]> kt: [{}];
    out property <[float]> kx: [{}];
    out property <[float]> ky: [{}];
    out property <duration> length: {}ms;
}}
",
        col(|k| k.0),
        col(|k| k.1),
        col(|k| k.2),
        squash::SQUASH_MS,
    );
    std::fs::write(out.join("squash-keys.slint"), text).expect("write squash-keys.slint");
}

fn main() {
    let out = PathBuf::from(std::env::var("OUT_DIR").expect("OUT_DIR"));
    write_squash_keys(&out);
    println!("cargo:rerun-if-changed=../wubble-core/src/motion/squash.rs");
    // Debug builds carry the element ids the headless tests look up (`ElementHandle`, i-slint-
    // backend-testing); release builds do not.
    let debug = std::env::var("PROFILE").is_ok_and(|p| p == "debug");
    let config = slint_build::CompilerConfiguration::new()
        .with_debug_info(debug)
        .with_include_paths(vec![out]);
    slint_build::compile_with_config("ui/app.slint", config).expect("slint compile failed");
}
